def get_digit_at_position(k):
    left, right = 1, 10**9
    while left < right:
        mid = (left + right) // 2
        length = sum(range(1, mid + 1))
        if k <= length:
            right = mid
        else:
            k -= length
            left = mid + 1
    block_length = len(str(left))
    return int(str(left)[(k - 1) % block_length])

